<?php require_once __DIR__.'/../config/database.php'; require_once __DIR__.'/../config/auth.php'; require_login(); header('Content-Type:text/csv'); header('Content-Disposition:attachment; filename="campus-network-report.csv"'); $o=fopen('php://output','w'); fputcsv($o,['Device','IP','Type','Location','Status','Limit Mbps','Download Mbps','Upload Mbps','Last Seen']); foreach($pdo->query('SELECT device_name,ip_address,device_type,location,status,bandwidth_limit,download_mbps,upload_mbps,last_seen FROM devices') as $r)fputcsv($o,$r); fclose($o);
